<?php session_start();$AUTH_PASSWORD='';define('FM_ROOT_PATH',realpath(__DIR__));$ALLOW_ZIP=class_exists('ZipArchive');function get_abs($r){$p=FM_ROOT_PATH.($r!==''?DIRECTORY_SEPARATOR.trim(str_replace(array('../','..\\',"\0"),'',(string)$r),'/\\'):'');$rp=realpath($p);return($rp&&strpos($rp,FM_ROOT_PATH)===0)?$rp:((!file_exists($p)&&strpos(realpath(dirname($p))?realpath(dirname($p)):'',FM_ROOT_PATH)===0)?$p:FM_ROOT_PATH);}function get_rel($a){return($a===FM_ROOT_PATH)?'':trim(str_replace('\\','/',substr($a,strlen(FM_ROOT_PATH))),'/');}function get_url($p='',$act='',$ex=array()){return basename($_SERVER['PHP_SELF']).'?'.http_build_query(array_filter(array_merge(array('p'=>$p),$act?array('action'=>$act):array(),$ex),'strlen'));}function format_bytes($b){$u=array('B','KB','MB','GB','TB');return $b<=0?'0 B':round($b/pow(1024,$p=min((int)floor(log($b,1024)),4)),2).' '.$u[$p];}function is_edit($e){return in_array($e,array('txt','php','html','htm','css','js','json','xml','md','py','sql','sh','env','ini','conf','csv','yaml','yml','log','svg','htaccess'));}function delete_rec($t){if(!file_exists($t))return false;if(!is_dir($t))return@unlink($t);foreach(array_diff(scandir($t),array('.','..'))as $f)delete_rec($t.DIRECTORY_SEPARATOR.$f);return@rmdir($t);}function get_dir_stats($dir){$s=$f=$d=0;if(is_dir($dir)){foreach(new RecursiveIteratorIterator(new RecursiveDirectoryIterator($dir,FilesystemIterator::SKIP_DOTS),RecursiveIteratorIterator::SELF_FIRST)as $i){$i->isDir()?$d++:($f++&&($s+=$i->getSize()));}}return array('size'=>$s,'files'=>$f,'dirs'=>$d);}if(!empty($AUTH_PASSWORD)){if(isset($_POST['login_pass'])){if($_POST['login_pass']===$AUTH_PASSWORD){$_SESSION['fm_logged']=true;header('Location: '.$_SERVER['PHP_SELF']);exit;}$login_err='Invalid password.';}if((isset($_GET['action'])?$_GET['action']:'')==='logout'){unset($_SESSION['fm_logged']);header('Location: '.$_SERVER['PHP_SELF']);exit;}if(empty($_SESSION['fm_logged'])){echo '<!doctype html><html><head><meta charset="utf-8"><title>Login</title></head><body><main><h1>BoringManager</h1>'.(!empty($login_err)?'<p>'.$login_err.'</p>':'').'<form method="POST"><label>Master Password</label> <input type="password" name="login_pass" required autofocus> <button type="submit">Unlock</button></form></main></body></html>';exit;}}$cur_abs=get_abs(isset($_REQUEST['p'])?$_REQUEST['p']:'');$cur_rel=get_rel($cur_abs);$msg=isset($_GET['msg'])?$_GET['msg']:'';if($_SERVER['REQUEST_METHOD']==='POST'){if(isset($_POST['do_chunk_upload'],$_FILES['chunk_file'])){header('Content-Type: application/json');$fn=basename(trim(str_replace(array("\0",'/','\\'),'',isset($_POST['file_name'])?$_POST['file_name']:'')));$idx=(int)(isset($_POST['chunk_index'])?$_POST['chunk_index']:0);$tmp=sys_get_temp_dir().DIRECTORY_SEPARATOR.'fm_'.md5(preg_replace('/[^a-zA-Z0-9_-]/','',isset($_POST['upload_token'])?$_POST['upload_token']:'').$fn).'.tmp';$in=fopen($_FILES['chunk_file']['tmp_name'],'rb');$out=fopen($tmp,$idx===0?'wb':'ab');if($in&&$out){while(!feof($in))fwrite($out,fread($in,8192));}if($in)fclose($in);if($out)fclose($out);if($idx+1>=(int)(isset($_POST['total_chunks'])?$_POST['total_chunks']:1)){@rename($tmp,$cur_abs.DIRECTORY_SEPARATOR.$fn);echo json_encode(array('status'=>'complete'));}else{echo json_encode(array('status'=>'chunk_ok'));}exit;}if(isset($_POST['new_folder'])&&($fn=trim(str_replace(array('/','\\','..'),'',isset($_POST['folder_name'])?$_POST['folder_name']:'')))!==''){@mkdir($cur_abs.DIRECTORY_SEPARATOR.$fn,0755,true)?$msg="Folder created.":$msg="Failed creating folder.";}elseif(isset($_POST['new_file'])&&($fn=trim(str_replace(array('/','\\','..'),'',isset($_POST['file_name'])?$_POST['file_name']:'')))!==''){file_put_contents($cur_abs.DIRECTORY_SEPARATOR.$fn,'')!==false?$msg="File created.":$msg="Failed creating file.";}elseif(isset($_POST['edit_file'])&&is_file($fa=get_abs(isset($_POST['file'])?$_POST['file']:''))){$ok=file_put_contents($fa,isset($_POST['content'])?$_POST['content']:'')!==false;header('Location: '.get_url($cur_rel,'edit',array('file'=>get_rel($fa),'msg'=>$ok?'File saved successfully.':'Failed to save file.')));exit;}elseif(isset($_POST['rename_item'])&&file_exists($sa=get_abs(isset($_POST['target'])?$_POST['target']:''))){$nn=trim(str_replace(array('/','\\','..'),'',isset($_POST['new_name'])?$_POST['new_name']:''));if($nn!=='')@rename($sa,dirname($sa).DIRECTORY_SEPARATOR.$nn);header('Location: '.get_url($cur_rel));exit;}elseif(isset($_POST['delete_item'])&&($ta=get_abs(isset($_POST['target'])?$_POST['target']:''))!==FM_ROOT_PATH){delete_rec($ta);header('Location: '.get_url($cur_rel));exit;}elseif(isset($_POST['batch_delete'])&&!empty($_POST['targets'])&&is_array($_POST['targets'])){$c=0;foreach($_POST['targets'] as $t){if(($ta=get_abs($t))!==FM_ROOT_PATH&&file_exists($ta)){delete_rec($ta);$c++;}}header('Location: '.get_url($cur_rel,'',array('msg'=>"$c item(s) deleted.")));exit;}elseif(isset($_POST['batch_zip'])&&$ALLOW_ZIP&&!empty($_POST['targets'])&&is_array($_POST['targets'])){$zip=new ZipArchive();$zn=$cur_abs.DIRECTORY_SEPARATOR.'archive_'.date('Ymd_His').'.zip';if($zip->open($zn,ZipArchive::CREATE|ZipArchive::OVERWRITE)===true){foreach($_POST['targets'] as $t){if(file_exists($sa=get_abs($t))){if(is_dir($sa)){foreach(new RecursiveIteratorIterator(new RecursiveDirectoryIterator($sa,4096),1)as $f){$r=basename($sa).'/'.substr($f->getPathname(),strlen($sa)+1);$f->isDir()?$zip->addEmptyDir($r):$zip->addFile($f->getPathname(),$r);}}else{$zip->addFile($sa,basename($sa));}}}$zip->close();$msg='Archive created.';}}elseif(isset($_POST['zip_item'])&&$ALLOW_ZIP&&file_exists($sa=get_abs(isset($_POST['target'])?$_POST['target']:''))){$zip=new ZipArchive();if($zip->open($sa.'.zip',ZipArchive::CREATE|ZipArchive::OVERWRITE)===true){if(is_dir($sa)){foreach(new RecursiveIteratorIterator(new RecursiveDirectoryIterator($sa,4096),1)as $f){$r=substr($f->getPathname(),strlen($sa)+1);$f->isDir()?$zip->addEmptyDir($r):$zip->addFile($f->getPathname(),$r);}}else{$zip->addFile($sa,basename($sa));}$zip->close();$msg='Archived.';}}elseif(isset($_POST['unzip_item'])&&$ALLOW_ZIP&&is_file($sa=get_abs(isset($_POST['target'])?$_POST['target']:''))){$zip=new ZipArchive();if($zip->open($sa)===true){$zip->extractTo(dirname($sa));$zip->close();$msg='Extracted.';}}}$act=isset($_GET['action'])?$_GET['action']:'list';if($act==='download'&&is_file($fa=get_abs(isset($_GET['file'])?$_GET['file']:''))){if(session_id())session_write_close();while(ob_get_level())ob_end_clean();header('Content-Type: application/octet-stream');header('Content-Disposition: attachment; filename="'.basename($fa).'"');header('Content-Length: '.filesize($fa));readfile($fa);exit;}if($act==='raw'&&is_file($fa=get_abs(isset($_GET['file'])?$_GET['file']:''))){$ext=strtolower(pathinfo($fa,PATHINFO_EXTENSION));$m=array('jpg'=>'image/jpeg','jpeg'=>'image/jpeg','png'=>'image/png','gif'=>'image/gif','webp'=>'image/webp','svg'=>'image/svg+xml','mp3'=>'audio/mpeg','wav'=>'audio/wav','ogg'=>'audio/ogg','mp4'=>'video/mp4','webm'=>'video/webm','pdf'=>'application/pdf','txt'=>'text/plain','json'=>'application/json');$mime=isset($m[$ext])?$m[$ext]:'application/octet-stream';$size=filesize($fa);$start=0;$end=$size-1;if(session_id())session_write_close();while(ob_get_level())ob_end_clean();header('Content-Type: '.$mime);header('Accept-Ranges: bytes');if(isset($_SERVER['HTTP_RANGE'])){if(preg_match('/bytes=\s*(\d+)?\s*-\s*(\d+)?/i',$_SERVER['HTTP_RANGE'],$matches)){if(isset($matches[1])&&$matches[1]!==''&&(!isset($matches[2])||$matches[2]==='')){$start=intval($matches[1]);$end=$size-1;}elseif((!isset($matches[1])||$matches[1]==='')&&isset($matches[2])&&$matches[2]!==''){$start=$size-intval($matches[2]);$end=$size-1;}elseif(isset($matches[1],$matches[2])&&$matches[1]!==''&&$matches[2]!==''){$start=intval($matches[1]);$end=min(intval($matches[2]),$size-1);}}if($start>$end||$start>=$size){header('HTTP/1.1 416 Requested Range Not Satisfiable');header('Content-Range: bytes */'.$size);exit;}header('HTTP/1.1 206 Partial Content');header('Content-Range: bytes '.$start.'-'.$end.'/'.$size);header('Content-Length: '.($end-$start+1));}else{header('HTTP/1.1 200 OK');header('Content-Length: '.$size);}$fp=fopen($fa,'rb');if($fp){fseek($fp,$start);$cur=$start;while(!feof($fp)&&$cur<=$end&&!connection_aborted()){$buf=min(65536,$end-$cur+1);echo fread($fp,$buf);$cur+=$buf;flush();}fclose($fp);}exit;} ?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>BoringManager</title></head><body><header><nav><a href="<?=get_url()?>"><strong>Root</strong></a><?php $accum='';foreach(array_filter(explode('/',$cur_rel),'strlen')as $seg):$accum.=($accum===''?'':'/').$seg; ?> / <a href="<?=get_url($accum)?>"><?=htmlspecialchars($seg)?></a><?php endforeach; ?><?php if(!empty($AUTH_PASSWORD)): ?> | <a href="<?=get_url($cur_rel,'logout')?>">Logout</a><?php endif; ?></nav><h1>BoringManager</h1></header><main><?php if(!empty($msg)): ?><p><strong><?=htmlspecialchars($msg)?></strong></p><?php endif; ?><?php if($act==='info'&&file_exists($ta=get_abs(isset($_GET['target'])?$_GET['target']:''))):$is_d=is_dir($ta);$st=$is_d?get_dir_stats($ta):array('size'=>filesize($ta),'files'=>1,'dirs'=>0); ?><h3>Info: <?=htmlspecialchars(basename($ta))?></h3><ul><li><strong>Type:</strong> <?=$is_d?'Directory':'File ('.strtoupper(pathinfo($ta,PATHINFO_EXTENSION)).')'?></li><li><strong>Path:</strong> /<?=htmlspecialchars(get_rel($ta))?></li><li><strong>Total Size:</strong> <?=format_bytes($st['size'])?> (<?=number_format($st['size'])?> B)</li><li><strong>All Subpath Files:</strong> <?=$st['files']?> file(s)<?=$is_d?', '.$st['dirs'].' folder(s)':''?></li><li><strong>Permissions:</strong> <code><?=substr(sprintf('%o',fileperms($ta)),-4)?></code> (R:<?=is_readable($ta)?'Yes':'No'?>, W:<?=is_writable($ta)?'Yes':'No'?>)</li><li><strong>Last Modified:</strong> <?=date('Y-m-d H:i:s',filemtime($ta))?></li></ul><p><a href="<?=get_url($cur_rel)?>"><button type="button">Back</button></a></p><?php elseif($act==='edit'&&is_file($fa=get_abs(isset($_GET['file'])?$_GET['file']:''))&&is_edit(strtolower(pathinfo($fa,PATHINFO_EXTENSION)))): ?><h3>Edit: <?=htmlspecialchars(basename($fa))?></h3><form method="POST"><input type="hidden" name="p" value="<?=htmlspecialchars($cur_rel)?>"><input type="hidden" name="file" value="<?=htmlspecialchars(get_rel($fa))?>"><textarea name="content" rows="18" cols="80" style="max-width:100%;box-sizing:border-box"><?=htmlspecialchars(file_get_contents($fa))?></textarea><p><button type="submit" name="edit_file" value="1">Save</button> <a href="<?=get_url($cur_rel)?>"><button type="button">Cancel</button></a></p></form><?php elseif($act==='view'&&is_file($fa=get_abs(isset($_GET['file'])?$_GET['file']:''))):$ext=strtolower(pathinfo($fa,PATHINFO_EXTENSION));$m=array('jpg'=>'image/jpeg','jpeg'=>'image/jpeg','png'=>'image/png','gif'=>'image/gif','webp'=>'image/webp','svg'=>'image/svg+xml','mp3'=>'audio/mpeg','wav'=>'audio/wav','ogg'=>'audio/ogg','mp4'=>'video/mp4','webm'=>'video/webm','pdf'=>'application/pdf'); ?><h3>Preview: <?=htmlspecialchars(basename($fa))?> (<?=format_bytes(filesize($fa))?>)</h3><p><a href="<?=get_url($cur_rel,'info',array('target'=>get_rel($fa)))?>"><button type="button">Info</button></a> <?php if(is_edit($ext)): ?><a href="<?=get_url($cur_rel,'edit',array('file'=>get_rel($fa)))?>"><button type="button">Edit</button></a> <?php endif; ?><a href="<?=get_url($cur_rel,'download',array('file'=>get_rel($fa)))?>"><button type="button">Download</button></a> <a href="<?=get_url($cur_rel)?>"><button type="button">Back</button></a></p><?php if(in_array($ext,array('jpg','jpeg','png','gif','webp','svg'))): ?><p><img src="<?=get_url($cur_rel,'raw',array('file'=>get_rel($fa)))?>" style="max-width:100%;max-height:85vh;height:auto;display:block"></p><?php elseif(in_array($ext,array('mp3','wav','ogg'))): ?><p><audio controls preload="metadata" style="width:100%;max-width:100%"><source src="<?=get_url($cur_rel,'raw',array('file'=>get_rel($fa)))?>" type="<?=isset($m[$ext])?$m[$ext]:''?>"></audio></p><?php elseif(in_array($ext,array('mp4','webm'))): ?><p><video controls preload="metadata" style="max-width:100%;max-height:85vh;width:auto;height:auto;display:block"><source src="<?=get_url($cur_rel,'raw',array('file'=>get_rel($fa)))?>" type="<?=isset($m[$ext])?$m[$ext]:''?>"></video></p><?php elseif($ext==='pdf'): ?><iframe src="<?=get_url($cur_rel,'raw',array('file'=>get_rel($fa)))?>" style="width:100%;height:85vh;border:none"></iframe><?php else: ?><pre style="max-width:100%;overflow:auto"><code><?=htmlspecialchars(file_get_contents($fa))?></code></pre><?php endif; ?><?php elseif($act==='rename'&&file_exists($ta=get_abs(isset($_GET['target'])?$_GET['target']:''))): ?><h3>Rename: <?=htmlspecialchars(basename($ta))?></h3><form method="POST"><input type="hidden" name="p" value="<?=htmlspecialchars($cur_rel)?>"><input type="hidden" name="target" value="<?=htmlspecialchars(get_rel($ta))?>"><input type="text" name="new_name" value="<?=htmlspecialchars(basename($ta))?>" autofocus required><p><button type="submit" name="rename_item" value="1">Save</button> <a href="<?=get_url($cur_rel)?>"><button type="button">Cancel</button></a></p></form><?php else:$q=trim(isset($_GET['q'])?$_GET['q']:'');$items=array();if($q!==''&&is_dir($cur_abs)){foreach(new RecursiveIteratorIterator(new RecursiveDirectoryIterator($cur_abs,FilesystemIterator::SKIP_DOTS),RecursiveIteratorIterator::SELF_FIRST)as $f){if(stripos($f->getFilename(),$q)!==false){$path=$f->getPathname();$is_d=$f->isDir();$items[]=array('name'=>$f->getFilename(),'path'=>$path,'is_dir'=>$is_d,'size'=>$is_d?0:$f->getSize(),'mtime'=>$f->getMTime(),'perms'=>substr(sprintf('%o',$f->getPerms()),-4),'rel'=>get_rel($path),'ext'=>strtolower(pathinfo($path,PATHINFO_EXTENSION)));}}}elseif(is_dir($cur_abs)){$sc=scandir($cur_abs);if($sc!==false){foreach(array_diff($sc,array('.','..'))as $name){$path=$cur_abs.DIRECTORY_SEPARATOR.$name;$is_d=is_dir($path);$items[]=array('name'=>$name,'path'=>$path,'is_dir'=>$is_d,'size'=>$is_d?0:filesize($path),'mtime'=>filemtime($path),'perms'=>substr(sprintf('%o',fileperms($path)),-4),'rel'=>get_rel($path),'ext'=>strtolower(pathinfo($path,PATHINFO_EXTENSION)));}}}usort($items,function($a,$b){return $a['is_dir']===$b['is_dir']?strcasecmp($a['name'],$b['name']):($a['is_dir']?-1:1);}); ?><section><form method="GET"><input type="hidden" name="p" value="<?=htmlspecialchars($cur_rel)?>"><input type="search" name="q" value="<?=htmlspecialchars($q)?>" placeholder="Search subpaths..."> <button type="submit">Search</button><?php if($q!==''): ?> <a href="<?=get_url($cur_rel)?>"><button type="button">Clear</button></a><?php endif; ?></form><details><summary>Upload / Create</summary><div><form onsubmit="startChunkUpload(event)"><input type="file" id="cf" multiple required> <button type="submit">Upload</button></form><form method="POST"><input type="hidden" name="p" value="<?=htmlspecialchars($cur_rel)?>"><input type="text" name="folder_name" placeholder="Folder" required> <button type="submit" name="new_folder" value="1">+ Folder</button></form><form method="POST"><input type="hidden" name="p" value="<?=htmlspecialchars($cur_rel)?>"><input type="text" name="file_name" placeholder="File" required> <button type="submit" name="new_file" value="1">+ File</button></form></div><p id="cp" style="display:none"><strong id="cpt">Uploading...</strong></p></details></section><form method="POST"><input type="hidden" name="p" value="<?=htmlspecialchars($cur_rel)?>"><div><h3>Total: <?=count($items)?> item(s)</h3><div><button type="submit" name="batch_delete" value="1" onclick="return confirm('Delete all selected items?')">Delete Selected</button> <?php if($ALLOW_ZIP): ?><button type="submit" name="batch_zip" value="1">Zip Selected</button><?php endif; ?></div></div><table><thead><tr><th><input type="checkbox" id="chk-all" title="Select All"></th><th>Name</th><th>Size</th><th>Modified</th><th>Perms</th><th>Actions</th></tr></thead><tbody><?php if($cur_rel!==''&&$q===''): ?><tr><td></td><td colspan="5"><a href="<?=get_url(dirname($cur_rel)==='.'?'':dirname($cur_rel))?>">.. (Parent)</a></td></tr><?php endif; ?><?php if(empty($items)): ?><tr><td colspan="6">No items found.</td></tr><?php endif; ?><?php foreach($items as $it): ?><tr><td><input type="checkbox" name="targets[]" value="<?=htmlspecialchars($it['rel'])?>" class="batch-chk"></td><td><a href="<?=$it['is_dir']?get_url($it['rel']):get_url($cur_rel,'view',array('file'=>$it['rel']))?>"><?=$it['is_dir']?'['.htmlspecialchars($it['name']).']':htmlspecialchars($it['name'])?></a><?php if($q!==''): ?><br><small>/<?=htmlspecialchars($it['rel'])?></small><?php endif; ?></td><td><?=$it['is_dir']?'-':format_bytes($it['size'])?></td><td><small><?=date('Y-m-d H:i',$it['mtime'])?></small></td><td><code><?=$it['perms']?></code></td><td><details><summary>Actions</summary><div><a href="<?=get_url($cur_rel,'info',array('target'=>$it['rel']))?>">Info</a><?php if(!$it['is_dir']): ?> | <a href="<?=get_url($cur_rel,'view',array('file'=>$it['rel']))?>">View</a><?php if(is_edit($it['ext'])): ?> | <a href="<?=get_url($cur_rel,'edit',array('file'=>$it['rel']))?>">Edit</a><?php endif; ?> | <a href="<?=get_url($cur_rel,'download',array('file'=>$it['rel']))?>">Download</a><?php endif; ?> | <a href="<?=get_url($cur_rel,'rename',array('target'=>$it['rel']))?>">Rename</a><?php if($ALLOW_ZIP&&$it['ext']==='zip'): ?> | <button type="submit" name="unzip_item" value="1" formaction="<?=get_url($cur_rel)?>" onclick="this.form.target.value='<?=htmlspecialchars($it['rel'],ENT_QUOTES)?>';return confirm('Extract zip?')">Unzip</button><?php elseif($ALLOW_ZIP): ?> | <button type="submit" name="zip_item" value="1" formaction="<?=get_url($cur_rel)?>" onclick="this.form.target.value='<?=htmlspecialchars($it['rel'],ENT_QUOTES)?>'">Zip</button><?php endif; ?> | <button type="submit" name="delete_item" value="1" formaction="<?=get_url($cur_rel)?>" onclick="this.form.target.value='<?=htmlspecialchars($it['rel'],ENT_QUOTES)?>';return confirm('Delete <?=htmlspecialchars($it['name'],ENT_QUOTES)?>?')">Del</button></div></details></td></tr><?php endforeach; ?></tbody></table><input type="hidden" name="target" value=""></form><?php endif; ?></main><script>document.getElementById('chk-all')&&document.getElementById('chk-all').addEventListener('click',function(){var c=document.querySelectorAll('.batch-chk');for(var i=0;i<c.length;i++)c[i].checked=this.checked;});var lastChk=null;document.addEventListener('click',function(e){if(e.target&&e.target.classList.contains('batch-chk')){if(!lastChk)lastChk=e.target;if(e.shiftKey){var chks=Array.prototype.slice.call(document.querySelectorAll('.batch-chk')),s=chks.indexOf(lastChk),en=chks.indexOf(e.target),sub=chks.slice(Math.min(s,en),Math.max(s,en)+1);for(var i=0;i<sub.length;i++)sub[i].checked=lastChk.checked;}lastChk=e.target;}});async function startChunkUpload(e){e.preventDefault();var files=document.getElementById('cf').files,prog=document.getElementById('cp'),txt=document.getElementById('cpt');if(!files.length)return;prog.style.display='block';var sz=2*1024*1024;for(var f=0;f<files.length;f++){var file=files[f],chunks=Math.ceil(file.size/sz)||1,tok=Date.now()+'_'+f;for(var i=0;i<chunks;i++){var fd=new FormData();fd.append('do_chunk_upload','1');fd.append('p','<?=htmlspecialchars($cur_rel,ENT_QUOTES)?>');fd.append('file_name',file.name);fd.append('chunk_index',i);fd.append('total_chunks',chunks);fd.append('upload_token',tok);fd.append('chunk_file',file.slice(i*sz,Math.min((i+1)*sz,file.size)),file.name);txt.innerText='Uploading ('+(f+1)+'/'+files.length+'): '+file.name+' - '+Math.round(((i+1)/chunks)*100)+'%';await fetch(window.location.pathname,{method:'POST',body:fd});}}window.location.reload();}</script></body></html>
